-- Згенеровано з каталогу проду ${PROJECT_REF}, 13.08.2026.
-- 9 послідовностей + 51 таблиця. Констрейнти, індекси, RLS — окремими файлами.

create sequence if not exists public.app_settings_id_seq as integer start with 1 increment by 1 no cycle;
create sequence if not exists public.daily_stats_id_seq as bigint start with 1 increment by 1 no cycle;
create sequence if not exists public.order_statuses_id_seq as integer start with 1 increment by 1 no cycle;
create sequence if not exists public.page_view_hashes_id_seq as bigint start with 1 increment by 1 no cycle;
create sequence if not exists public.page_views_id_seq as bigint start with 1 increment by 1 no cycle;
create sequence if not exists public.services_translations_id_seq as integer start with 1 increment by 1 no cycle;
create sequence if not exists public.settings_id_seq as integer start with 1 increment by 1 no cycle;
create sequence if not exists public.site_settings_id_seq as integer start with 1 increment by 1 no cycle;
create sequence if not exists public.webhook_logs_id_seq as bigint start with 1 increment by 1 no cycle;

create table if not exists public.activities (id uuid default gen_random_uuid() not null, user_id uuid, action_type character varying(50) not null, entity_type character varying(50) not null, entity_id uuid, details jsonb, created_at timestamp with time zone default now() not null);
create table if not exists public.app_settings (id integer default nextval('app_settings_id_seq'::regclass) not null, key character varying(255) not null, value text not null, description text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.article_service_links (id uuid default gen_random_uuid() not null, article_id uuid not null, service_id uuid not null, "position" integer default 0, created_at timestamp with time zone default CURRENT_TIMESTAMP);
create table if not exists public.article_translations (id uuid default gen_random_uuid() not null, article_id uuid not null, locale text not null, title text not null, content text not null, meta_description text, created_at timestamp with time zone default CURRENT_TIMESTAMP, updated_at timestamp with time zone default CURRENT_TIMESTAMP, category text, slug character varying(255) not null);
create table if not exists public.articles (id uuid default gen_random_uuid() not null, slug text not null, title text not null, content text not null, meta_description text, featured boolean default false, published boolean default false, view_count integer default 0, reading_time_minutes integer default 1, featured_image text, created_at timestamp with time zone default CURRENT_TIMESTAMP, updated_at timestamp with time zone default CURRENT_TIMESTAMP, tags text[] default '{}'::text[], published_at timestamp with time zone, category text default 'General'::text, primary_service_id uuid, featured_image_type text default 'url'::text);
create table if not exists public.brands (id uuid default gen_random_uuid() not null, name character varying(255) not null, logo_url text, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, "position" integer, slug text);
create table if not exists public.catalog_descriptions (id uuid default gen_random_uuid() not null, scope_type text not null, scope_id uuid not null, locale text not null, description text, body text, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);
create table if not exists public.contact_messages (id uuid default gen_random_uuid() not null, name text not null, email text not null, phone text, message text not null, status text default 'new'::text not null, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.daily_stats (id bigint default nextval('daily_stats_id_seq'::regclass) not null, date date not null, page_path text not null, view_count bigint default 0 not null, unique_visitors bigint default 0 not null, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.discount_usages (id uuid default gen_random_uuid() not null, discount_id uuid not null, user_id uuid, order_id uuid, used_at timestamp with time zone default now(), discount_amount numeric(10,2) not null, original_price numeric(10,2) not null, final_price numeric(10,2) not null);
create table if not exists public.discounts (id uuid default gen_random_uuid() not null, name character varying(255) not null, code character varying(50) not null, description text, discount_type character varying(20) not null, discount_value numeric(10,2) not null, service_ids uuid[] default '{}'::uuid[] not null, scope_type character varying(50) not null, brand_id uuid, series_id uuid, model_id uuid, is_active boolean default true, starts_at timestamp with time zone, expires_at timestamp with time zone, max_uses integer, current_uses integer default 0, max_uses_per_user integer, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), user_id uuid, requires_code boolean default false not null, show_as_offer boolean default false not null, offer_title text, offer_description text, offer_priority integer default 0 not null);
create table if not exists public.email_verification_tokens (id uuid default uuid_generate_v4() not null, user_id uuid not null, token character varying(255) not null, expires_at timestamp with time zone not null, created_at timestamp with time zone default now());
create table if not exists public.hero_carousel_settings (id uuid default gen_random_uuid() not null, enabled boolean default false, autoplay_interval integer default 5000, updated_at timestamp with time zone default now());
create table if not exists public.hero_carousel_slides (id uuid default gen_random_uuid() not null, image_url text not null, link text default '/'::text not null, sort_order integer default 0, created_at timestamp with time zone default now());
create table if not exists public.legal_documents (id uuid default gen_random_uuid() not null, slug text not null, title_cs text default ''::text not null, title_uk text default ''::text not null, title_en text default ''::text not null, content text default ''::text not null, is_active boolean default true not null, required_at_registration boolean default false not null, sort_order integer default 0 not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);
create table if not exists public.login_attempts (id uuid default uuid_generate_v4() not null, email character varying(255) not null, attempt_count integer default 1 not null, last_attempt_at timestamp with time zone default now(), blocked_until timestamp with time zone, created_at timestamp with time zone default now());
create table if not exists public.model_services (id uuid default gen_random_uuid() not null, model_id uuid not null, service_id uuid not null, price numeric(10,2), created_at timestamp with time zone default now(), warranty_months integer, duration_hours numeric(4,2) default NULL::numeric, warranty_period character varying(20) default 'months'::character varying, detailed_description text, what_included text, benefits text, part_type character varying(255));
create table if not exists public.models (id uuid default gen_random_uuid() not null, brand_id uuid not null, name character varying(255) not null, image_url text, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, "position" integer default 0, series_id uuid, slug text);
create table if not exists public.order_status_history (id uuid default gen_random_uuid() not null, order_id uuid not null, user_id uuid not null, old_status character varying(255) not null, new_status character varying(255) not null, changed_by character varying(255) not null, changed_at timestamp with time zone not null, created_at timestamp with time zone default now());
create table if not exists public.order_statuses (id integer default nextval('order_statuses_id_seq'::regclass) not null, remonline_status_id integer not null, name_uk character varying(100) not null, name_en character varying(100) not null, name_cs character varying(100) not null, color character varying(50) default 'bg-gray-100'::character varying not null, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.page_view_hashes (id bigint default nextval('page_view_hashes_id_seq'::regclass) not null, date date not null, page_path text not null, visitor_hash character varying(64) not null, created_at timestamp with time zone default now());
create table if not exists public.page_views (id bigint default nextval('page_views_id_seq'::regclass) not null, page_path text not null, visitor_hash text not null, session_id text, created_at timestamp with time zone default CURRENT_TIMESTAMP);
create table if not exists public.password_reset_tokens (id uuid default uuid_generate_v4() not null, user_id uuid not null, token character varying(255) not null, expires_at timestamp with time zone not null, created_at timestamp with time zone default now());
create table if not exists public.profiles (id uuid not null, first_name character varying(255), phone character varying(50), avatar_url text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), address character varying(255), email character varying(255), last_name character varying(255), billing_street text, billing_city text, billing_postal_code character varying(20), billing_country character varying(2) default 'CZ'::character varying);
create table if not exists public.promotional_banners (id uuid default gen_random_uuid() not null, enabled boolean default false, color character varying(100) default 'bg-orange-500'::character varying, text_cs text not null, text_en text not null, text_uk text not null, button_text_cs character varying(255) default 'Отримати знижку'::character varying, button_text_en character varying(255) default 'Get discount'::character varying, button_text_uk character varying(255) default 'Отримати знижку'::character varying, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), button_link text);
create table if not exists public.remonline_categories (id uuid default gen_random_uuid() not null, category_id bigint not null, category_title character varying(255) not null, description text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.remonline_order_sync_issues (id uuid default gen_random_uuid() not null, remonline_event_id text not null, event_name text not null, remonline_order_id integer, remonline_client_id integer, status text default 'open'::text not null, reason text not null, details text, raw_payload jsonb default '{}'::jsonb not null, attempts integer default 1 not null, first_seen_at timestamp with time zone default now(), last_seen_at timestamp with time zone default now(), resolved_at timestamp with time zone, resolved_by uuid, ignored_at timestamp with time zone, ignored_by uuid, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.remonline_services (id uuid default gen_random_uuid() not null, remonline_id bigint not null, service_id uuid, brand_id uuid, series_id uuid, model_id uuid, title character varying(255) not null, cost numeric(10,2) default 0, price numeric(10,2) default 0, duration_minutes integer default 0, warranty_months integer default 0, barcode character varying(255), category_id bigint, parsed_service_slug character varying(255), parsed_brand_slug character varying(255), parsed_series_slug character varying(255), parsed_model_slug character varying(255), service_slug_found boolean default false, brand_slug_found boolean default false, series_slug_found boolean default false, model_slug_found boolean default false, sync_status character varying(50) default 'pending'::character varying, sync_error text, needs_review boolean default false, last_synced_at timestamp with time zone default now(), created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.remonline_sync_sessions (id uuid default gen_random_uuid() not null, session_id character varying(255) not null, phase character varying(50) default 'fetching'::character varying, total_services integer default 0, fetched_services integer default 0, parsed_services integer default 0, processed_services integer default 0, created_services integer default 0, updated_services integer default 0, error_services integer default 0, services_needing_review integer default 0, created_brands integer default 0, created_series integer default 0, created_models integer default 0, status character varying(50) default 'running'::character varying, current_service_title character varying(255), error_message text, started_at timestamp with time zone default now(), completed_at timestamp with time zone, created_at timestamp with time zone default now());
create table if not exists public.repair_order_items (id uuid default gen_random_uuid() not null, remonline_order_id bigint not null, remonline_item_id bigint not null, service_name text not null, quantity numeric(10,3) default 1.000, price numeric(10,2) default 0.00 not null, warranty_period integer, warranty_units text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.repair_orders (id uuid default uuid_generate_v4() not null, user_id uuid not null, remonline_id integer not null, reference_number character varying(255) not null, device_brand character varying(255) not null, device_model character varying(255) not null, service_type character varying(255) not null, status character varying(50) default 'unknown'::character varying not null, price numeric(10,2), created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, status_id text, status_name text, status_color text);
create table if not exists public.repairs (id uuid default gen_random_uuid() not null, user_id uuid, model_id uuid, repair_type character varying(255) not null, status character varying(50) default 'pending'::character varying not null, price numeric(10,2), notes text, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, completed_at timestamp with time zone);
create table if not exists public.roles (id uuid default gen_random_uuid() not null, name character varying(100) not null, slug character varying(50) not null, is_default boolean default false, auto_approve boolean default true, discount_percentage numeric(5,2) default 0, description text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.series (id uuid default gen_random_uuid() not null, name character varying(255) not null, brand_id uuid not null, "position" integer, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), slug text, image_url text);
create table if not exists public.service_faq_translations (id uuid default gen_random_uuid() not null, faq_id uuid, locale character varying(5) not null, question text not null, answer text not null, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.service_faqs (id uuid default gen_random_uuid() not null, service_id uuid, "position" integer default 0, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.service_scope_faq_translations (id uuid default gen_random_uuid() not null, faq_id uuid not null, locale text not null, question text not null, answer text not null);
create table if not exists public.service_scope_faqs (id uuid default gen_random_uuid() not null, service_id uuid not null, scope_type text not null, scope_id uuid not null, "position" integer default 0 not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);
create table if not exists public.service_scope_translations (id uuid default gen_random_uuid() not null, service_id uuid not null, scope_type text not null, scope_id uuid not null, locale text not null, detailed_description text, what_included text, benefits text, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);
create table if not exists public.services (id uuid default gen_random_uuid() not null, name character varying(255) not null, description text, "position" integer default 0, created_at timestamp with time zone default now(), slug character varying(255), warranty_months integer default 12, duration_hours numeric(3,1) default 1.0, image_url text);
create table if not exists public.services_translations (id integer default nextval('services_translations_id_seq'::regclass) not null, service_id uuid, locale character varying(10) not null, name character varying(255) not null, description text, detailed_description text, what_included text, benefits text);
create table if not exists public.sessions (id uuid default uuid_generate_v4() not null, user_id uuid not null, expires_at timestamp with time zone not null, created_at timestamp with time zone default now());
create table if not exists public.settings (id integer default nextval('settings_id_seq'::regclass) not null, key text not null, value jsonb not null, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.site_settings (id integer default nextval('site_settings_id_seq'::regclass) not null, setting_key character varying(255) not null, setting_value text not null, description text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.user_invoice_orders (id uuid default gen_random_uuid() not null, invoice_id uuid not null, remonline_invoice_id integer not null, order_id uuid, remonline_order_id integer not null, user_id uuid, raw_payload jsonb default '{}'::jsonb not null, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.user_invoices (id uuid default gen_random_uuid() not null, remonline_invoice_id integer not null, user_id uuid, invoice_number text not null, status_id integer, status_name text, status_group text, issue_date timestamp with time zone, due_date timestamp with time zone, created_at_remonline timestamp with time zone, modified_at_remonline timestamp with time zone, payment_method text, client_id integer, client_name text, payer_id integer, payer_name text, manager_id integer, manager_name text, subtotal_amount numeric(12,2), discount_amount numeric(12,2), total_amount numeric(12,2), paid_amount numeric(12,2), balance_amount numeric(12,2), currency text, raw_payload jsonb default '{}'::jsonb not null, sync_source text default 'webhook'::text not null, sync_status text default 'synced'::text not null, sync_error text, is_deleted boolean default false not null, last_synced_at timestamp with time zone, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.user_repair_order_services (id uuid default gen_random_uuid() not null, order_id uuid not null, remonline_order_id integer not null, remonline_service_id integer, service_name character varying(255) not null, price numeric(10,2) default 0 not null, warranty_period integer, warranty_units character varying(50), service_status character varying(100) default 'active'::character varying, service_status_name character varying(255) default 'Активна'::character varying, service_status_color character varying(255) default 'bg-blue-100 text-blue-800'::character varying, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.user_repair_orders (id uuid default gen_random_uuid() not null, remonline_order_id integer not null, user_id uuid not null, document_id character varying(255) not null, creation_date timestamp with time zone not null, device_serial_number character varying(255), device_name character varying(255) not null, device_brand character varying(255), device_model character varying(255), total_amount numeric(10,2), overall_status character varying(100) not null, overall_status_name character varying(255), overall_status_color character varying(255), created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table if not exists public.users (id uuid default uuid_generate_v4() not null, email character varying(255) not null, password_hash character varying(255) not null, role character varying(50) default 'user'::character varying not null, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), email_verified boolean default false, first_name text, remonline_id integer, last_name character varying(255), name character varying(255), role_id uuid, ico character varying(20), dic character varying(20), is_b2b boolean default false, is_approved boolean default true, remonline_contact_type text, remonline_sync_status text, remonline_sync_error text, remonline_synced_at timestamp with time zone, remonline_sync_attempts integer default 0 not null, company_name text, locale text default 'uk'::text not null);
create table if not exists public.verification_codes (id uuid default uuid_generate_v4() not null, user_id uuid, email text not null, code text not null, type text not null, expires_at timestamp with time zone not null, created_at timestamp with time zone default now());
create table if not exists public.webhook_logs (id bigint default nextval('webhook_logs_id_seq'::regclass) not null, event_type text default 'unknown'::text not null, status text not null, message text default ''::text, processing_time_ms integer default 0, webhook_data jsonb default '{}'::jsonb not null, created_at timestamp with time zone default now());
